import{_ as i,o as t,c as s,a3 as r,j as e,a}from"./chunks/framework.z_KJ15Ep.js";const u="/bilder/unterricht-kataloge/kataloge-kurse.png",l="/bilder/unterricht-kataloge/kataloge-neuen-kurs-anlegen.png",K=JSON.parse('{"title":"Kursunterricht anlegen und zuweisen","description":"","frontmatter":{"title":"Kursunterricht anlegen und zuweisen","source_pageid":358,"source_revision":5247},"headers":[],"relativePath":"schild3/unterricht-kataloge/kursunterrichte-anlegen-tutorial.md","filePath":"schild3/unterricht-kataloge/kursunterrichte-anlegen-tutorial.md"}'),h={name:"schild3/unterricht-kataloge/kursunterrichte-anlegen-tutorial.md"};function g(d,n,c,o,b,m){return t(),s("div",null,[...n[0]||(n[0]=[r('<h1 id="kursunterricht-anlegen-und-zuweisen" tabindex="-1">Kursunterricht anlegen und zuweisen <a class="header-anchor" href="#kursunterricht-anlegen-und-zuweisen" aria-label="Permalink to &quot;Kursunterricht anlegen und zuweisen&quot;">​</a></h1><p>Legen Sie Kurse für Unterricht an, der nicht im gesamten Klassenverband stattfindet. Erst danach können Sie die Kurse einzelnen Schülerinnen und Schülern oder einer Gruppe zuweisen.</p><p><a href="/bilder/unterricht-kataloge/kataloge-kurse.png"><img src="'+u+'" alt="Übersicht über die Kurse." loading="lazy"></a></p><p><em>Übersicht über die Kurse.</em></p><p><strong>Kursunterricht</strong> wird einer bestimmten Schülergruppe zugeordnet. Im Unterschied zum Klassenunterricht nimmt nicht die gesamte Klasse gemeinsam daran teil.</p><p>Dieser Unterricht wird in SchILD-NRW mit der <em>Kursart</em> PUT (Pflichtunterricht für Teile von Klassen) bezeichnet. Daneben gibt es noch weitere Bezeichnungen wie zum Beispiel AG, DFG, FUT, LRS.</p><p>Unter dem Reiter <em>Kataloge</em> befindet sich den Unterpunkt <strong>Kurse</strong>. Hier gibt es die Möglichkeit für jeden Jahrgang und gegebenenfalls auch für einzelne Klassen Kurse anzulegen.</p>',7),e("div",{"data-hint-kind":"info",class:"info custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"info","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("circle",{cx:"12",cy:"12",r:"9"}),e("path",{d:"M12 11v6m0-10v.1"})]),a("Hinweis")]),e("p",null,'Kurse können den Schülerinnen und Schülern unter "Akt. Halbjahr" nur zugewiesen werden, wenn der jeweilige Kurs auch in dieser Tabelle angelegt worden ist.')],-1),r('<p>Die Schüler werden dann über die Gruppenprozesse oder individuell durch Hinzufügen im aktuellen Abschnitt zu den Kursen zugewiesen.</p><h2 id="kurse-filtern-und-bearbeiten" tabindex="-1">Kurse filtern und bearbeiten <a class="header-anchor" href="#kurse-filtern-und-bearbeiten" aria-label="Permalink to &quot;Kurse filtern und bearbeiten&quot;">​</a></h2><p>Um die Anzeige der Kurse einzuschränken oder Kurse aus anderen Halbjahren anzuzeigen, benutzen Sie bitte die <em>Schnellfilter</em> im oberen Bereich.</p><p>Es stehen Ihnen ein Excel-Export dieser Tabelle und einige Aktualisierungsmöglichkeiten zur Verfügung. Zusätzliche Jahrgänge bei jahrgangsübergreifenden Kursen (Spalte &quot;Mehrere Jahrgänge&quot;) können auf Knopfdruck ermittelt werden.</p><p><a href="/bilder/unterricht-kataloge/kataloge-neuen-kurs-anlegen.png"><img src="'+l+'" alt="Neuen Kurs anlegen." loading="lazy"></a></p><p><em>Neuen Kurs anlegen.</em></p><p>Neue Kurse werden über das Pluszeichen im oberen Bereich angelegt:</p><ul><li><strong>Kurs-Bez.:</strong> Die Kursbezeichnung kann frei gewählt werden: Zu beachten ist dabei, dass diese im jeweiligen Abschnitt eindeutig sein muss.</li><li><strong>Fach:</strong> Hier stehen alle Fächer zur Verfügung, die unter Kataloge -&gt; Unterrichtsfächer angelegt wurden. In manchen Fällen kann es sinnvoll sein, für Kurse eigene Fächer einzurichten.</li><li><strong>Jahrgänge:</strong> Ist ein Kurs nur für einen bestimmten Jahrgang, so wählen Sie diesen durch Setzen des Kreuzchens. Falls der Kurs in mehreren Jahrgängen stattfindet, setzen Sie die Kreuze bei mehreren Jahrgängen (z.B. 05 und 06).</li><li><strong>Kursart:</strong> Hier wird die Kursart des Kurses festgelegt. Diese allgemeine Kursart kann sich von den beim Schüler eingetragenen Kursarten unterscheiden. Z.B. wäre ein Grundkurs (GK) beim Schüler dann mit Grundkurs schriftl. (GKS) eingetragen. Auch sog. Differenzierungkurse (DK) an den Schulformen GE und SK würden bei den Schülern dann mit E-Kurs oder G-Kurs eingetragen.</li><li><strong>Kursleiter:</strong> Erster Kurslehrer, der den Kurs unterrichtet.</li><li><strong>Wochen-Zeiteinheiten:</strong> Zeiteinheit der Wochenstunden bei den Schülern.</li><li><strong>Fortschreibungsart:</strong> Die Fortschreibungsart bestimmt, wie bei der Versetzung mit dem Kurs umgegangen wird. Bitte beachten Sie, dass die Fortschreibungsart bei jedem Abschnittswechsel berücksichtigt wird! <ul><li><strong>keine:</strong> Der Kurs wird nicht in den Zielabschnitt fortgeschrieben.</li><li><strong>Nur Definition, Jg. beibehalten:</strong> Die Kursdefinition wird ohne Schülerzuordnungen in den Zielabschnitt übernommen; der Jahrgang bleibt bestehen.</li><li><strong>Nur Definition, Jg. hochschreiben:</strong> Die Kursdefinition wird ohne Schülerzuordnungen in den Zielabschnitt übernommen und der Jahrgang hochgeschrieben.</li><li><strong>Komplett:</strong> Der Kurs wird mit allen Schülern in den nächsten Abschnitt geführt. Beim Schuljahreswechsel wird der Jahrgang erhöht.</li></ul></li><li><strong>Zeugnisbezeichnung:</strong> Geben Sie hier eine Zeugnisbezeichnung ein, wenn das Kursfach eine andere Bezeichnung als das &quot;normale&quot; Fach haben soll.</li></ul><p>Prüfen Sie vor der Schülerzuweisung Fach, Jahrgang, Kursart und Abschnitt. Ein bereits belegter Kurs kann nicht einfach auf einen anderen Jahrgang umgestellt werden; siehe <a href="/schild3/unterricht-kataloge/kurse-schulbezogene-kataloge.html">Kurskatalog</a>.</p><hr><p><a href="https://schulverwaltungsinfos.nrw.de/svws/wiki/index.php?title=Kursunterrichte_anlegen_(Tutorial)" target="_blank" rel="noreferrer">Originalartikel im Wiki</a> · Quellrevision 5247.</p>',11)])])}const k=i(h,[["render",g]]);export{K as __pageData,k as default};
